{
  "id": "openclaw:core:dashboard",
  "source": "openclaw",
  "sourceName": "core",
  "name": "dashboard",
  "label": "Dashboard",
  "description": "Read and arrange this session dashboard; widget_put updates plugin widgets only. Follow the widget authoring tool's current placement guidance. Actions: read snapshot; tab_create/tab_update/tab_delete/tabs_reorder; widget_put/widget_move/widget_resize/widget_remove; focus_tab opens the dashboard side panel; set_presentation shows the dashboard alongside chat (split) or across the task area (expanded). focus_tab and set_presentation require a connected Control UI and do not save a default. set_default_presentation saves split or expanded for subsequent opens without requiring a connected UI; read returns the effective defaultPresentation (split when unset). Personal viewer overrides still take precedence. Widgets use stable names. widget_put creates or updates trusted plugin widgets only; update other content through its owning authoring capability discovered in the tool catalog. Prefer session:report for data reports with text, metrics, tables, charts, and links; it renders directly without a document frame. Use session:progress props {sessionKey?} for live session progress (omit sessionKey for the current session). Use session:website props {url} for a live HTTPS website; size full and expanded presentation fill the task area. Other widget kinds are supplied by enabled plugins. Sizes: sm=3x3, md=6x4, lg=8x6, xl=12x8, full=12x8 single-widget emphasis.",
  "input": "{ action: string; after?: string; name?: string; pluginKind?: string; position?: number /* integer, >= 0 */; presentation?: \"split\" | \"expanded\"; props?: { ... }; size?: \"sm\" | \"md\" | \"lg\" | \"xl\" | \"full\"; sizeH?: number /* integer, >= 1, <= 20 */; sizeW?: number /* integer, >= 1, <= 12 */; ... }",
  "parameters": {
    "type": "object",
    "required": [
      "action"
    ],
    "properties": {
      "action": {
        "type": "string",
        "enum": [
          "read",
          "tab_create",
          "tab_update",
          "tab_delete",
          "tabs_reorder",
          "widget_put",
          "widget_move",
          "widget_resize",
          "widget_remove",
          "focus_tab",
          "set_presentation",
          "set_default_presentation"
        ],
        "description": "Dashboard action; widget_put creates or updates trusted plugin widgets only"
      },
      "tabId": {
        "type": "string",
        "pattern": "^[a-z0-9-]{1,40}$",
        "description": "Stable tab slug"
      },
      "title": {
        "type": "string",
        "minLength": 1,
        "maxLength": 80,
        "description": "Tab title"
      },
      "presentation": {
        "type": "string",
        "enum": [
          "split",
          "expanded"
        ],
        "description": "Dashboard panel presentation"
      },
      "position": {
        "type": "integer",
        "minimum": 0,
        "description": "Zero-based position"
      },
      "tabIds": {
        "type": "array",
        "items": {
          "type": "string",
          "pattern": "^[a-z0-9-]{1,40}$"
        },
        "description": "Complete tab order"
      },
      "name": {
        "type": "string",
        "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$",
        "description": "Stable widget name"
      },
      "after": {
        "type": "string",
        "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$",
        "description": "Place after stable widget name"
      },
      "sizeW": {
        "type": "integer",
        "minimum": 1,
        "maximum": 12
      },
      "sizeH": {
        "type": "integer",
        "minimum": 1,
        "maximum": 20
      },
      "size": {
        "type": "string",
        "enum": [
          "sm",
          "md",
          "lg",
          "xl",
          "full"
        ]
      },
      "pluginKind": {
        "type": "string",
        "pattern": "^[a-z0-9][a-z0-9-]{0,63}:[a-z0-9][a-z0-9._-]{0,63}$",
        "description": "Registered widget kind; session:report renders data reports, session:progress renders live session progress, session:website embeds a live HTTPS website"
      },
      "props": {
        "type": "object",
        "patternProperties": {
          "^.*$": {}
        },
        "description": "Widget JSON props (maximum 8KB encoded). For session:report: Report data: {blocks:[...]}. Blocks: text {text,title?}; metrics {items:[{label,value,detail?}]}; table {columns,rows,title?}; chart {points:[{label,value}],style?:\"bar\"|\"line\",title?}; links {items:[{label,url,detail?}],title?}. Every block needs its type. Metric values and table cells are strings; chart values are numbers. Maximum 8KB JSON, 24 blocks, 8 metrics or columns, 40 rows or chart points, 20 links per block. Links must be HTTP(S). No HTML, scripts, styles, network reads, or executable actions. For session:website: Website props: {url:\"https://...\"}. Opens the live website in an isolated browser frame without Gateway tools or credentials. Use a public HTTPS URL without embedded credentials; the website must allow embedding. Some sign-in flows and browser cookie policies require opening the website separately. Use size:\"full\", then action:\"set_presentation\" with presentation:\"expanded\" for a full-task website."
      }
    },
    "additionalProperties": false
  }
}

