{
  "id": "openclaw:file-transfer:file_write",
  "source": "openclaw",
  "sourceName": "file-transfer",
  "name": "file_write",
  "label": "File Write",
  "description": "Write file bytes to a paired node by absolute path. Atomic write (temp + rename). Refuses to overwrite by default; pass overwrite=true to replace. Refuses to write through symlink targets unless policy explicitly allows following symlinks. Pass contentBase64 for inline bytes, or sourceMediaId for a previously fetched file's mediaId in the file-transfer media store. Requires operator opt-in: gateway.nodes.commands.allow must include 'file.write', and file-transfer policy must authorize the path through allowWritePaths or a remembered exact approval. Without policy configured, every call is denied.",
  "input": "{ node: string; path: string; contentBase64?: string; createParents?: boolean; mimeType?: string; overwrite?: boolean; sourceMediaId?: string }",
  "parameters": {
    "type": "object",
    "required": [
      "node",
      "path"
    ],
    "properties": {
      "node": {
        "type": "string",
        "description": "Existing paired node id, display name, or IP shown by nodes status. Do not use local, host, gateway, or auto; use local file/exec tools for local workspace paths."
      },
      "path": {
        "type": "string",
        "description": "Absolute path on the node to write. Canonicalized server-side."
      },
      "contentBase64": {
        "type": "string",
        "description": "Base64-encoded bytes to write. Maximum 16 MB after decode."
      },
      "sourceMediaId": {
        "type": "string",
        "description": "mediaId of a previously fetched file in the file-transfer media store. Reuses saved bytes for binary copies. Not a local path or an ID from another media store."
      },
      "mimeType": {
        "type": "string",
        "description": "Content type hint. Not validated against the content."
      },
      "overwrite": {
        "type": "boolean",
        "description": "Allow overwriting an existing file. Default false.",
        "default": false
      },
      "createParents": {
        "type": "boolean",
        "description": "Create missing parent directories (mkdir -p). Default false.",
        "default": false
      }
    }
  }
}

{
  "id": "openclaw:file-transfer:file_fetch",
  "source": "openclaw",
  "sourceName": "file-transfer",
  "name": "file_fetch",
  "label": "File Fetch",
  "description": "Retrieve a file from a paired node by absolute path. Saves all fetched bytes in the gateway's file-transfer media store and returns localPath and mediaId. Returns supported images as image content blocks and inlines small text files (≤8 KB). Use this for screenshots, photos, receipts, logs, source files. The mediaId can be reused as sourceMediaId for binary copies when node-write capability is available. Requires operator opt-in: gateway.nodes.commands.allow must include 'file.fetch', and file-transfer policy must authorize the path through allowReadPaths or a remembered exact approval. Without policy configured, every call is denied.",
  "input": "{ node: string; path: string; gatewayToken?: string; gatewayUrl?: string; maxBytes?: number /* integer, >= 1 */; timeoutMs?: number /* integer, >= 1 */ }",
  "parameters": {
    "type": "object",
    "required": [
      "node",
      "path"
    ],
    "properties": {
      "node": {
        "type": "string",
        "description": "Existing paired node id, display name, or IP shown by nodes status. Do not use local, host, gateway, or auto; use local file/exec tools for local workspace paths."
      },
      "path": {
        "type": "string",
        "description": "Absolute path to the file on the node. Canonicalized server-side."
      },
      "maxBytes": {
        "type": "integer",
        "minimum": 1,
        "description": "Max bytes to fetch. Default 8 MB, hard ceiling 16 MB (single round-trip)."
      },
      "gatewayUrl": {
        "type": "string"
      },
      "gatewayToken": {
        "type": "string"
      },
      "timeoutMs": {
        "type": "integer",
        "minimum": 1
      }
    }
  }
}

{
  "id": "openclaw:file-transfer:dir_fetch",
  "source": "openclaw",
  "sourceName": "file-transfer",
  "name": "dir_fetch",
  "label": "Directory Fetch",
  "description": "Retrieve a whole directory tree, including dotfiles, from a paired node as a gzipped tarball. Unpack it on the gateway. Text is limited to 8192 UTF-8 bytes and shows rootDir, total fileCount and a prefix of complete saved relPath and size records when representable; full files and media metadata stay in structured details. Use rootDir plus relPath for local follow-up operations. Omitted files remain saved under rootDir; inspect them with available local file or directory capabilities. There is no fetch pagination. A denied descendant rejects the whole transfer. Rejects trees larger than 16 MB compressed. Requires operator opt-in: gateway.nodes.commands.allow must include 'dir.fetch', and file-transfer policy must authorize the path through allowReadPaths or a remembered exact approval.",
  "input": "{ node: string; path: string; gatewayToken?: string; gatewayUrl?: string; maxBytes?: number /* integer, >= 1 */; timeoutMs?: number /* integer, >= 1 */ }",
