{
  "id": "openclaw:core:sessions",
  "source": "openclaw",
  "sourceName": "core",
  "name": "sessions",
  "label": "Sessions",
  "description": "cloud_profiles lists configured cloud profiles; pass profileId for their OS and machine choices. Session settings, ownership, stop, reset, delete, and custom sidebar groups: patch label/icon/group/status, pin, archive/restore, model/thinking override. patch with group files sessions into a group; targets applies the same patch to up to 100 visible sessions; group_list shows the catalog; group_set replaces the whole ordered catalog; group_rename/group_delete change one group everywhere. assign_owner hands responsibility to a human or agent; reset/delete visible sessions.",
  "input": "unknown",
  "parameters": {
    "type": "object",
    "required": [
      "action"
    ],
    "properties": {
      "user": {
        "type": "string",
        "description": "The person's requester_profile.id, required when several people have steered this turn."
      },
      "action": {
        "enum": [
          "cloud_profiles",
          "patch",
          "stop",
          "reset",
          "delete",
          "assign_owner",
          "group_list",
          "group_set",
          "group_rename",
          "group_delete"
        ],
        "type": "string",
        "description": "Action"
      },
      "profileId": {
        "type": "string",
        "minLength": 1,
        "maxLength": 256,
        "pattern": "^\\S(?:.*\\S)?$",
        "description": "cloud_profiles: return OS and machine choices for this configured profile.",
        "~optional": true
      },
      "offset": {
        "type": "integer",
        "minimum": 0,
        "description": "cloud_profiles: nextOffset from the previous profile-list page."
      },
      "sessionKey": {
        "type": "string",
        "description": "Target session. Default: current"
      },
      "targets": {
        "type": "array",
        "items": {
          "type": "object",
          "required": [
            "sessionKey"
          ],
          "properties": {
            "sessionKey": {
              "type": "string",
              "minLength": 1
            },
            "expectedSessionId": {
              "type": "string",
              "minLength": 1
            }
          },
          "additionalProperties": false
        },
        "minItems": 1,
        "maxItems": 100,
        "description": "patch: apply the same settings to these sessions. Cannot combine with top-level sessionKey/expectedSessionId. Archive/restore requires each target's expectedSessionId. Current-session archive uses a single patch. Results use zero-based succeeded/failed indexes; valid targets continue after item errors."
      },
      "expectedSessionId": {
        "type": "string",
        "description": "Durable identity returned by sessions_list; rejects a replaced session. Required to archive, restore, or delete another session, and for non-owner rename of another session."
      },
      "runId": {
        "type": "string",
        "description": "stop: cancel this exact active run, if specified."
      },
      "clearQueued": {
        "type": "boolean",
        "description": "stop: also clear queued follow-ups for session-wide stop. Default true; unavailable with runId."
      },
      "deleteTranscript": {
        "type": "boolean",
        "description": "Archive the deleted session transcript. Default: true."
      },
      "label": {
        "type": "string",
        "description": "Sidebar title override. Empty string clears it."
      },
      "icon": {
        "type": "string",
        "description": "Persistent sidebar icon: a single emoji, or a named icon: braces, book, monitor, bot, kanban, coins, or custom SVG markup/data:image/svg+xml URL (max 16 KiB decoded; self-contained, no scripts or external references). Include xmlns=\"http://www.w3.org/2000/svg\" and viewBox on SVGs. Empty string clears it. Distinct from temporary attention."
      },
      "color": {
        "type": "string",
        "description": "Persistent sidebar color tint, one of: red, blue, green, yellow, purple, orange, pink, cyan. Empty string clears it."
      },
      "group": {
        "anyOf": [
          {
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "description": "patch: custom sidebar group for this session. Null or an empty string clears it back to ungrouped; assigning a new name creates the group."
      },
      "statusNote": {
        "type": "string",
        "maxLength": 120,
        "description": "Short sidebar status line. Empty string clears it and declared attention. Clears automatically when the user reads or replies, or when its TTL expires."
      },
      "attention": {
        "enum": [
          "clear",
          "hand",
          "key",
          "alert",
          "flag",
          "lock",
          "hourglass"
        ],
        "type": "string",
        "description": "Request user attention with a curated icon; requires an active statusNote. 'clear' clears both attention and statusNote."
      },
      "ttlMinutes": {
        "type": "integer",
        "minimum": 1,
        "maximum": 120,
        "description": "Status/attention lifetime in minutes. Default 30; maximum 120."
      },
      "pinned": {
        "type": "boolean",
        "description": "Pin session (root and Home-linked sessions only; spawned, subagent, and nested-child sessions cannot be pinned)"
      },
      "archived": {
        "type": "boolean",
        "description": "True archives without deleting; false restores the session."
      },
      "model": {
        "type": "string",
        "description": "Model override"
      },
      "thinkingLevel": {
        "type": "string",
        "description": "Thinking override"
      },
      "ownerType": {
        "enum": [
          "human",
          "agent"
        ],
        "type": "string",
        "description": "New owner kind for assign_owner"
      },
      "ownerId": {
        "type": "string",
        "description": "New owner id for assign_owner"
      },
      "names": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "group_set: full replacement of the ordered group catalog. Array order becomes sidebar order; new names are created; empty groups left out are deleted. Dropping a group that still has member sessions is rejected — remove it with group_delete first. Never moves sessions. To reorder, pass the complete current list in the new order."
      },
      "name": {
        "type": "string",
        "description": "group_rename and group_delete: the group to act on."
      },
      "to": {
        "type": "string",
        "description": "group_rename: the new group name."
      }
    },
    "additionalProperties": false
  }
}

