{
  "id": "openclaw:core:sessions_history",
  "source": "openclaw",
  "sourceName": "core",
  "name": "sessions_history",
  "label": "Session History",
  "description": "Read sanitized visible-session history. Before reply/debug/resume. Use messageId for anchored history; sessionId selects its transcript and requires messageId. Omit both for the latest tail. offset pages unanchored history and is ignored with messageId. limit bounds either mode. Include tool messages with includeTools. pendingInputs are accepted inputs outside model history; page with pendingBefore=nextBefore. Cancelled/interrupted inputs never replay automatically. Lower limit for richer pending previews.",
  "input": "{ sessionKey: string; includeTools?: boolean; limit?: number /* integer, >= 1, <= 1000 */; messageId?: string; offset?: number /* integer, >= 0 */; pendingBefore?: number /* integer, >= 1 */; sessionId?: string; user?: string }",
  "output": "{ bytes: number; contentRedacted: boolean; contentTruncated: boolean; droppedMessages: boolean; messages: Array<unknown>; sessionKey: string; truncated: boolean; hasMore?: boolean; nextOffset?: number; offset?: number; pendingInputs?: { items: Array<{ acceptedAt: number; id: string; message: unknown; state: \"queued\" | \"cancelled\" | \"interrupted\"; queued?: true; runId?: string }>; total: number; nextBefore?: number; queuedCount?: number }; sessionLinkRule?: string; totalMessages?: number; windowReset?: boolean } | { error: string; status: \"error\" | \"forbidden\" }",
  "parameters": {
    "type": "object",
    "required": [
      "sessionKey"
    ],
    "properties": {
      "user": {
        "type": "string",
        "description": "The person's requester_profile.id, required when several people have steered this turn."
      },
      "sessionKey": {
        "type": "string",
        "minLength": 1
      },
      "limit": {
        "type": "integer",
        "minimum": 1,
        "maximum": 1000
      },
      "offset": {
        "type": "integer",
        "minimum": 0,
        "description": "Plain-pagination offset. Ignored when messageId is set; limit still bounds anchored history."
      },
      "pendingBefore": {
        "type": "integer",
        "minimum": 1
      },
      "messageId": {
        "type": "string",
        "minLength": 1,
        "description": "Return history around this message id. Ignores offset; limit bounds the window."
      },
      "sessionId": {
        "type": "string",
        "minLength": 1,
        "description": "Transcript session id that owns messageId. Requires messageId; omit for the latest tail."
      },
      "includeTools": {
        "type": "boolean"
      }
    }
  },
  "outputSchema": {
    "anyOf": [
      {
        "type": "object",
        "required": [
          "sessionKey",
          "messages",
          "truncated",
          "droppedMessages",
          "contentTruncated",
          "contentRedacted",
          "bytes"
        ],
        "properties": {
          "sessionKey": {
            "type": "string"
          },
          "messages": {
            "type": "array",
            "items": {}
          },
          "truncated": {
