  "id": "openclaw:memory-core:memory_get",
  "source": "openclaw",
  "sourceName": "memory-core",
  "name": "memory_get",
  "label": "Memory Get",
  "description": "Safe exact excerpt read from MEMORY.md, USER.md, Markdown files recursively under memory/. Session transcript paths are unsupported; use the available session-history workflow for session hits. Defaults to a bounded excerpt when lines are omitted and includes truncation/continuation info when more content exists. `corpus=wiki` reads registered compiled-wiki supplements. status=ok means the requested excerpt was read; status=not_found means every requested available corpus missed; status=error means the requested read failed, not that memory is disabled. Corpus outcomes cover each requested corpus; only a top-level corpus warning means results are partial and must be surfaced to the user. An optional corpus outcome of not-registered in a multi-corpus result is informational.",
  "input": "{ path: string; corpus?: \"memory\" | \"wiki\" | \"all\"; from?: number /* integer, >= 1 */; lines?: number /* integer, >= 1 */ }",
