{
  "id": "openclaw:file-transfer:file_write",
  "source": "openclaw",
  "sourceName": "file-transfer",
  "name": "file_write",
  "label": "File Write",
  "description": "Write file bytes to a paired node by absolute path. Atomic write (temp + rename). Refuses to overwrite by default; pass overwrite=true to replace. Refuses to write through symlink targets unless policy explicitly allows following symlinks. Pass contentBase64 for inline bytes, or sourceMediaId for a previously fetched file's mediaId in the file-transfer media store. Requires operator opt-in: gateway.nodes.commands.allow must include 'file.write', and file-transfer policy must authorize the path through allowWritePaths or a remembered exact approval. Without policy configured, every call is denied.",
  "input": "{ node: string; path: string; contentBase64?: string; createParents?: boolean; mimeType?: string; overwrite?: boolean; sourceMediaId?: string }",
  "parameters": {
    "type": "object",
    "required": [
      "node",
      "path"
    ],
    "properties": {
      "node": {
        "type": "string",
        "description": "Existing paired node id, display name, or IP shown by nodes status. Do not use local, host, gateway, or auto; use local file/exec tools for local workspace paths."
      },
      "path": {
        "type": "string",
        "description": "Absolute path on the node to write. Canonicalized server-side."
      },
      "contentBase64": {
        "type": "string",
        "description": "Base64-encoded bytes to write. Maximum 16 MB after decode."
      },
      "sourceMediaId": {
        "type": "string",
        "description": "mediaId of a previously fetched file in the file-transfer media store. Reuses saved bytes for binary copies. Not a local path or an ID from another media store."
      },
      "mimeType": {
        "type": "string",
        "description": "Content type hint. Not validated against the content."
      },
      "overwrite": {
        "type": "boolean",
        "description": "Allow overwriting an existing file. Default false.",
        "default": false
      },
      "createParents": {
        "type": "boolean",
        "description": "Create missing parent directories (mkdir -p). Default false.",
        "default": false
      }
    }
  }
}

